local a=require("ExcelTool")local b=a.Pack;local c=a.Sub;local d=a.LangGet;local e=a.Dmap;local f=require("Excels.Data.item_definition.skin")local g=f.tb;local h=f.get;g[400304]=b({e[21034],400304,3,17,17,"「やっほー！　森に入り込んだのってファンさんだったんだぁ。よく魔女の森に入れたね。さては特別な能力を持ってるんでしょ？　佳奈ちゃんがじっくり実験させてもらっちゃいま～す！」",200003,2,"deco/character/tengtianjianai_ws",false,false,false,false,false,false,false,"1",false,false,false,"120,-60,1",1802,818,418,1335,731,1769,1922,1335,731,1769,1056,false,false,false,false,false,false,false,false,false,false,false,false,"tengtianjianai_ws"},h)g[400305]=b({e[9034],400305,2,18,18,"「ライブ大成功を祝して、アイスクリームとココナッツウォーターをたっぷり堪能しちゃおーっ☆　その前に一枚パシャリと……。え、ええ？　太るよって？　ちょっとぐらい気を緩めたっていいじゃん……。」",200003,2,"deco/character/tengtianjianai_xr",1902,885,380,624,776,2506,3056,624,776,2506,1059,1,4093,5000,2496,4922,8000,13833,16333,8000,11000,8000,8000,"tengtianjianai_xr"},h)g[400306]=b({e[21034],400306,6,19,19,"「え～、もう来ちゃったの？　まだメイク終わってないのにー。あっでも、これってつまり、春節で私が一番最初に会った人はファンさんってことになるよね。佳奈ちゃん嬉しい！　あけましておめでとっ！」",200003,2,"deco/character/tengtianjianai_cj",false,false,false,false,false,false,false,"1",false,false,false,"240,-140,0.95",1926,885,400,1113,false,2076,3235,1113,584,2076,false,1,1905,5000,906,2860,5333,8666,7566,11033,16000,8000,5333,"tengtianjianai_cj"},h)g[400307]=b({e[9044],400307,21,20,20,"「ライブ前に緊張してた時にはいつも、ファンさんが応援してくれた。\nだから今日は、佳奈ちゃんがファンさんの応援をするよ！\nフレー、フレー！ ゴー！ ゴー！」",200003,2,"deco/character/tengtianjianai_ydh",0,false,false,false,false,false,false,false,false,false,false,false,false,"tengtianjianai_ydh"},h)g[400401]=b({e[17023],400401,false,21,21,false,200004,false,"deco/character/qianzhi",302002,60,false,false,false,false,-6,"1","0,-40,1","-50,70,1","0,60,1",false,false,false,"-40,90,1","-10,90,1",false,false,false,1853,1001,420,1351,700,1472,2520,1351,710,1472},h)g[400402]=b({e[11034],400402,1,4,22,"口ではイヤイヤ言いつつも、一つずつぬいぐるみコレクションを手に取る千織は、やっぱりかわいい！",200004,1,"deco/character/qianzhi_0",302002,60,1821,990,410,1172,572,1992,2612,1172,694,1992},h)g[400403]=b({e[9034],400403,4,16,23,"「毎年クリスマスになると、プレゼントがいっぱいね。そこのあんた、早くプレゼントを開けるのを手伝いなさい！　フン！　これはあんたへのプレゼントじゃないわ、お駄賃よお駄賃！」",200004,2,"deco/character/qianzhi_SDJ",1841,1009,401,1150,704,2015,2049,1150,709,2015},h)g[400404]=b({e[12034],400404,2,22,24,"「この千織様の可愛さに見合う水着を選ぶなんて、庶民のくせに、センスは悪くないじゃない。まあ……御褒美に写真くらいは撮らせてあげるわ、ふん！」",200004,2,"deco/character/qianzhi_YZ",false,false,1,2080,1076,400,1164,730,1714,1678,1164,775,1714},h)g[400405]=b({e[12034],400405,8,23,25,"「10分経ってもまだ決まらないなんて、どうせ千織のことジロジロ見てたんでしょ？」",200004,2,"deco/character/qianzhi_NP",false,false,1,1767,929,395,960,559,2010,2657,960,626,2010},h)g[400406]=b({e[21034],400406,3,24,26,"「ボーっと突っ立ってんじゃないわよ！　さっさと千織の服を直しなさい！　……じ、自分で出来ないなんて、そんなわけないじゃない！　下僕のくせにろくに働かないから、わざわざこの千織様自ら注意してやってるの！」",200004,2,"deco/character/400406",false,false,false,false,false,false,false,false,false,false,false,"100,-180,1",1962,999,412,983,793,1975,1838,983,793,1975,1172,1,2676,2550,1472,2473,8000,12333,8000,8000,12000,false,8000},h)g[400407]=b({e[21034],400407,6,19,27,"「商売繫盛、千ドラ万来、国士十三面待ち！　どう？　千織様からの新年を祝う言葉よ。　気に入ったわよね？　アンタはこれから、感激の涙を流しながら、千織と麻雀を打つの。今の言葉が現実になるかもしれないわ！」",200004,2,"deco/character/qianzhi_CJ",false,false,false,false,false,false,false,"1",false,false,false,"240,-180,0.95",1854,871,410,877,82,2543,2783,877,575,2543},h)g[400501]=b({e[46057],400501,false,25,28,false,200005,false,"deco/character/xiangyuanwu",302002,60,false,1,false,false,-7,"0.97",false,false,false,false,false,false,false,"0,190,0.98","0,0,0.97","80,0,0.97","0,0,0.97","0,0,0.97","0,0,0.97","0,0,0.97","0,0,0.97","0,0,0.97",false,false,1830,883,430,1614,798,1044,2701,1614,798,1044,1060,"xiangyuanwu"},h)g[400502]=b({e[13034],400502,1,4,29,"「旦那様に捧げるお神楽……これからもずっと、ずっと見ていてくださいね」\nそう言って舞う姿は、なんとも幻想的だった。",200005,1,"deco/character/xiangyuanwu_0",302002,60,false,1,1841,988,393,1028,677,2146,2822,1100,684,2002,false,false,false,false,false,false,false,false,false,false,false,false,false,"xiangyuanwu_0"},h)